import 'package:flutter_local_notifications/flutter_local_notifications.dart'; import 'package:timezone/data/latest.dart' as tz; import 'package:timezone/timezone.dart' as tz; import '../models/recurring_bill.dart';
class NotificationService { NotificationService._(); static final instance=NotificationService._(); final plugin=FlutterLocalNotificationsPlugin(); Future<void> init() async { tz.initializeTimeZones(); await plugin.initialize(const InitializationSettings(android:AndroidInitializationSettings('@mipmap/ic_launcher'))); await plugin.resolvePlatformSpecificImplementation<AndroidFlutterLocalNotificationsPlugin>()?.requestNotificationsPermission(); } Future<void> schedule(RecurringBill b) async { final now=tz.TZDateTime.now(tz.local); var date=tz.TZDateTime(tz.local,now.year,now.month,b.dueDay,9); if(date.isBefore(now)) date=tz.TZDateTime(tz.local,now.year,now.month+1,b.dueDay,9); date=date.subtract(Duration(days:b.reminderDays)); await plugin.zonedSchedule(b.id??DateTime.now().millisecondsSinceEpoch.remainder(1<<31),'Bill due soon', '${b.name} – ₹${b.amount.toStringAsFixed(0)}',date,const NotificationDetails(android:AndroidNotificationDetails('bills','Recurring bills',channelDescription:'Bill reminders',importance:Importance.high,priority:Priority.high)),androidScheduleMode:AndroidScheduleMode.exactAllowWhileIdle,matchDateTimeComponents:DateTimeComponents.dayOfMonth,uiLocalNotificationDateInterpretation:UILocalNotificationDateInterpretation.absoluteDate); } }
